private persist(patch: Partial<Omit<LocalState, 'schemaVersion'>>): void {
  this.persisted = { ...this.persisted, ...patch };
  // Coalesce: if a save is already waiting with an older snapshot, replace it with this one.
  this.savePending = this.persisted;
  if (this.saveChain === undefined) this.saveChain = Promise.resolve();
  this.saveChain = this.saveChain.then(async () => {
    const snapshot = this.savePending;
    this.savePending = undefined;
    if (snapshot === undefined) return;
    try {
      const result = await this.deps.saveLocalState(snapshot);
      if (result !== undefined && result !== null && result.state !== undefined) {
        // Adopt the post-merge snapshot so later patches (e.g. another project's history)
        // build on what is actually on disk, not on this process's stale view.
        this.persisted = result.state;
      }
      if (result?.warning !== undefined) {
        this.showNotice(`Local state warning: ${result.warning}`, 'warn');
      }
    } catch (error) {
      const message = errorText(error);
      this.debugLog.write('backend-error', { operation: 'save', kind: 'unknown' });
      this.saveError = message;
      this.showNotice(`Could not persist local state: ${message}`, 'error');
    }
  });
}

