524: function diffLineFg(kind: PatchLine['kind'], theme: Theme): string {
525:   switch (kind) {
526:     case 'add':
527:       return theme.success;
528:     case 'del':
529:       return theme.error;
530:     case 'hunk':
531:       return theme.accent;
532:     case 'meta':
